CREATE TABLE IF NOT EXISTS demo_requests (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name varchar(150) NOT NULL,phone varchar(15) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),status varchar(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','CONTACTED','SCHEDULED','CLOSED'))); CREATE INDEX IF NOT EXISTS demo_requests_status_created_idx ON demo_requests(status,created_at);